// Package controltest holds a deterministic PLACEHOLDER signing key for tests.
//
// The key is derived from a public string, so anyone can reproduce it: it
// protects nothing and must never be embedded in a release. Production code
// does not import this package, so it is not linked into the papio binary.
// The real control key pair is generated by `papio-control keygen`; only its
// public half is embedded, in internal/adaptercontrol/trust.go.
package controltest

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
)

const placeholderSeed = "papio adapter control PLACEHOLDER test-only key; protects nothing"

// PlaceholderKey returns the test-only key pair.
func PlaceholderKey() (ed25519.PublicKey, ed25519.PrivateKey) {
	seed := sha256.Sum256([]byte(placeholderSeed))
	private := ed25519.NewKeyFromSeed(seed[:])
	return private.Public().(ed25519.PublicKey), private
}

// PlaceholderPublicKeyBase64 is the base64 form `-ldflags -X` and the embedded
// key variable expect.
func PlaceholderPublicKeyBase64() string {
	public, _ := PlaceholderKey()
	return base64.StdEncoding.EncodeToString(public)
}

// OtherKey returns a second deterministic key pair, for wrong-key tests.
func OtherKey() (ed25519.PublicKey, ed25519.PrivateKey) {
	seed := sha256.Sum256([]byte(placeholderSeed + " (other)"))
	private := ed25519.NewKeyFromSeed(seed[:])
	return private.Public().(ed25519.PublicKey), private
}
